import re

class Tokenizer:
    def __init__(self, text):
        self.text = text
        self.pos = 0
        self.tokens = []
        self.tokenize()

    def tokenize(self):
        token_specification = [
            ('NUMBER',   r'\d+(\.\d*)?'),
            ('STRING',   r'"(?:\\.|[^"\\])*"'),
            ('ID',       r'[a-zA-Z_][a-zA-Z0-9_]*'),
            ('DOT',      r'\.'),
            ('PIPE',     r'\|'),
            ('COMMA',    r','),
            ('LBRACKET', r'\['),
            ('RBRACKET', r'\]'),
            ('LBRACE',   r'\{'),
            ('RBRACE',   r'\}'),
            ('LPAREN',   r'\('),
            ('RPAREN',   r'\)'),
            ('COLON',    r':'),
            ('DOLLAR',   r'\$'),
            ('OP',       r'[+\-*/%<>=!]+'),
            ('SKIP',     r'[ \t\n]+'),
            ('MISMATCH', r'.'),
        ]
        tok_regex = '|'.join('(?P<%s>%s)' % pair for pair in token_specification)
        for mo in re.finditer(tok_regex, self.text):
            kind = mo.lastgroup
            value = mo.group()
            if kind == 'NUMBER':
                value = float(value) if '.' in value else int(value)
            elif kind == 'STRING':
                value = json.loads(value)
            elif kind == 'SKIP':
                continue
            elif kind == 'MISMATCH':
                raise RuntimeError(f'{value!r} unexpected')
            self.tokens.append((kind, value))
        self.tokens.append(('EOF', None))

class Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def peek(self):
        return self.tokens[self.pos]

    def eat(self, kind=None):
        tk_kind, tk_val = self.peek()
        if kind and tk_kind != kind:
            raise RuntimeError(f'Expected {kind}, got {tk_kind}')
        self.pos += 1
        return tk_val

    def parse(self):
        return self.parse_comma()

    def parse_comma(self):
        nodes = [self.parse_pipe()]
        while self.peek()[0] == 'COMMA':
            self.eat('COMMA')
            nodes.append(self.parse_pipe())
        return ('COMMA', nodes) if len(nodes) > 1 else nodes[0]

    def parse_pipe(self):
        nodes = [self.parse_primary()]
        while self.peek()[0] == 'PIPE':
            self.eat('PIPE')
            nodes.append(self.parse_primary())
        return ('PIPE', nodes) if len(nodes) > 1 else nodes[0]

    def parse_primary(self):
        # Basic primary: identity, field access, brackets, etc.
        token_kind, token_val = self.peek()

        node = None
        if token_kind == 'DOT':
            self.eat('DOT')
            next_kind, next_val = self.peek()
            if next_kind == 'ID':
                node = ('FIELD', self.eat('ID'))
            elif next_kind == 'LBRACKET':
                node = ('IDENTITY', None) # We'll handle the bracket in the loop
            else:
                node = ('IDENTITY', None)
        elif token_kind == 'LPAREN':
            self.eat('LPAREN')
            node = self.parse_comma()
            self.eat('RPAREN')
        elif token_kind == 'ID':
            name = self.eat('ID')
            # could be a function call
            node = ('FUNC', name, [])
        else:
            # Handle literals
            if token_kind in ('NUMBER', 'STRING'):
                node = ('LITERAL', self.eat())
            else:
                raise RuntimeError(f'Unexpected token {token_kind}')

        # Postfixes: .foo, [index], etc.
        while True:
            tk_kind, tk_val = self.peek()
            if tk_kind == 'DOT':
                self.eat('DOT')
                nk, nv = self.peek()
                if nk == 'ID':
                    node = ('PIPE', [node, ('FIELD', self.eat('ID'))])
                elif nk == 'LBRACKET':
                    # handled by the next LBRACKET check
                    pass
                else:
                    # just a dot, probably next is another filter
                    # but . followed by nothing or special is just identity
                    # Actually, . . is not valid in jq usually, but let's see
                    break
            elif tk_kind == 'LBRACKET':
                self.eat('LBRACKET')
                if self.peek()[0] == 'RBRACKET':
                    self.eat('RBRACKET')
                    node = ('PIPE', [node, ('ITER', None)])
                else:
                    # Index or slice
                    index = self.parse_comma()
                    self.eat('RBRACKET')
                    node = ('PIPE', [node, ('INDEX', index)])
            else:
                break
        return node
