import argparse
import re
from itertools import chain

class Tokenizer:
    def __init__(self, text):
        self.text = text
        self.pos = 0
        self.tokens = []
        self.tokenize()

    def tokenize(self):
        token_specification = [
            ('NUMBER',   r'\d+(\.\d*)?'),
            ('STRING',   r'"(?:\\.|[^"\\])*"'),
            ('ID',       r'[a-zA-Z_][a-zA-Z0-9_]*'),
            ('DOT',      r'\.'),
            ('PIPE',     r'\|'),
            ('COMMA',    r','),
            ('LBRACKET', r'\['),
            ('RBRACKET', r'\]'),
            ('LBRACE',   r'\{'),
            ('RBRACE',   r'\}'),
            ('LPAREN',   r'\('),
            ('RPAREN',   r'\)'),
            ('COLON',    r':'),
            ('DOLLAR',   r'\$'),
            ('OP',       r'[+\-*/%<>=!]+'),
            ('SKIP',     r'[ \t\n]+'),
            ('MISMATCH', r'.'),
        ]
        tok_regex = '|'.join('(?P<%s>%s)' % pair for pair in token_specification)
        for mo in re.finditer(tok_regex, self.text):
            kind = mo.lastgroup
            value = mo.group()
            if kind == 'NUMBER':
                value = float(value) if '.' in value else int(value)
            elif kind == 'STRING':
                value = json.loads(value)
            elif kind == 'SKIP':
                continue
            elif kind == 'MISMATCH':
                raise RuntimeError(f'Unexpected character: {value}')
            self.tokens.append((kind, value))
        self.tokens.append(('EOF', None))

class Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def peek(self):
        return self.tokens[self.pos]

    def eat(self, kind=None):
        tk_kind, tk_val = self.peek()
        if kind and tk_kind != kind:
            raise RuntimeError(f'Expected {kind}, got {tk_kind}')
        self.pos += 1
        return tk_val

    def parse(self):
        if self.peek()[0] == 'EOF':
            return ('IDENTITY',)
        return self.parse_comma()

    def parse_comma(self):
        nodes = [self.parse_pipe()]
        while self.peek()[0] == 'COMMA':
            self.eat('COMMA')
            nodes.append(self.parse_pipe())
        return ('COMMA', nodes) if len(nodes) > 1 else nodes[0]

    def parse_pipe(self):
        nodes = [self.parse_primary()]
        while self.peek()[0] == 'PIPE':
            self.eat('PIPE')
            nodes.append(self.parse_primary())
        return ('PIPE', nodes) if len(nodes) > 1 else nodes[0]

    def parse_primary(self):
        token_kind, token_val = self.peek()

        node = None
        if token_kind == 'DOT':
            self.eat('DOT')
            nk, nv = self.peek()
            if nk == 'ID':
                node = ('FIELD', self.eat('ID'))
            elif nk == 'STRING':
                node = ('FIELD', self.eat('STRING'))
            elif nk == 'LBRACKET':
                node = ('IDENTITY',)
            else:
                node = ('IDENTITY',)
        elif token_kind == 'LPAREN':
            self.eat('LPAREN')
            node = self.parse_comma()
            self.eat('RPAREN')
        elif token_kind == 'ID':
            name = self.eat('ID')
            if self.peek()[0] == 'LPAREN':
                self.eat('LPAREN')
                args = []
                if self.peek()[0] != 'RPAREN':
                    args.append(self.parse_comma())
                    while self.peek()[0] == 'COMMA': # This might be wrong for multi-arg functions
                        self.eat('COMMA')
                        args.append(self.parse_comma())
                self.eat('RPAREN')
                node = ('FUNC', name, args)
            else:
                if name in ('null', 'true', 'false'):
                    vals = {'null': None, 'true': True, 'false': False}
                    node = ('LITERAL', vals[name])
                else:
                    node = ('FUNC', name, [])
        elif token_kind in ('NUMBER', 'STRING'):
            node = ('LITERAL', self.eat())
        elif token_kind == 'LBRACKET':
            self.eat('LBRACKET')
            if self.peek()[0] == 'RBRACKET':
                self.eat('RBRACKET')
                node = ('ARRAY_CONSTRUCT', None) # empty array []
            else:
                # Could be [ .[] | ... ] or [1, 2, 3]
                content = self.parse_comma()
                self.eat('RBRACKET')
                node = ('ARRAY_CONSTRUCT', content)
        elif token_kind == 'LBRACE':
            # Object construct {a: 1, "b": .c}
            self.eat('LBRACE')
            entries = []
            if self.peek()[0] != 'RBRACE':
                while True:
                    # Key can be ID, STRING, or (expr)
                    nk, nv = self.peek()
                    if nk == 'ID':
                        key = self.eat('ID')
                    elif nk == 'STRING':
                        key = self.eat('STRING')
                    elif nk == 'LPAREN':
                        self.eat('LPAREN')
                        key = ('KEY_EXPR', self.parse_comma())
                        self.eat('RPAREN')
                    else:
                        raise RuntimeError(f"Unexpected key type {nk}")

                    if self.peek()[0] == 'COLON':
                        self.eat('COLON')
                        val = self.parse_pipe()
                    else:
                        # Shortcut {a} is {a: .a}
                        val = ('FIELD', key)

                    entries.append((key, val))
                    if self.peek()[0] == 'COMMA':
                        self.eat('COMMA')
                    else:
                        break
            self.eat('RBRACE')
            node = ('OBJ_CONSTRUCT', entries)
        else:
            raise RuntimeError(f'Unexpected token {token_kind} ({token_val})')

        # Postfixes
        while True:
            tk_kind, tk_val = self.peek()
            if tk_kind == 'DOT':
                self.eat('DOT')
                nk, nv = self.peek()
                if nk == 'ID':
                    node = ('PIPE', [node, ('FIELD', self.eat('ID'))])
                elif nk == 'STRING':
                    node = ('PIPE', [node, ('FIELD', self.eat('STRING'))])
                elif nk == 'LBRACKET':
                    pass # handled below
                else:
                    # e.g., .a.
                    break
            elif tk_kind == 'LBRACKET':
                self.eat('LBRACKET')
                if self.peek()[0] == 'RBRACKET':
                    self.eat('RBRACKET')
                    node = ('PIPE', [node, ('ITER',)])
                else:
                    # Index or Slice
                    # Simplified: [idx] or [start:end]
                    # Since parse_comma is used, we need to handle COLON
                    # For now, just index
                    index_expr = self.parse_comma()
                    # Check for slice
                    if self.peek()[0] == 'COLON':
                        self.eat('COLON')
                        # ...
                        pass
                    self.eat('RBRACKET')
                    node = ('PIPE', [node, ('INDEX', index_expr)])
            else:
                break
        return node

def execute(node, value):
    ntype = node[0]
    if ntype == 'IDENTITY':
        yield value
    elif ntype == 'FIELD':
        key = node[1]
        if isinstance(value, dict):
            yield value.get(key)
        else:
            yield None
    elif ntype == 'PIPE':
        nodes = node[1]
        current_values = [value]
        for n in nodes:
            next_values = []
            for v in current_values:
                next_values.extend(execute(n, v))
            current_values = next_values
        yield from current_values
    elif ntype == 'COMMA':
        for n in node[1]:
            yield from execute(n, value)
    elif ntype == 'ITER':
        if isinstance(value, list):
            yield from value
        elif isinstance(value, dict):
            yield from value.values()
    elif ntype == 'INDEX':
        # node[1] is an expression for the index
        for idx in execute(node[1], value):
            if isinstance(value, list) and isinstance(idx, int):
                if 0 <= idx < len(value):
                    yield value[idx]
                elif -len(value) <= idx < 0:
                    yield value[idx]
                else:
                    yield None
            elif isinstance(value, dict) and isinstance(idx, str):
                yield value.get(idx)
            else:
                yield None
    elif ntype == 'LITERAL':
        yield node[1]
    elif ntype == 'ARRAY_CONSTRUCT':
        content_node = node[1]
        if content_node is None:
            yield []
        else:
            yield list(execute(content_node, value))
    elif ntype == 'OBJ_CONSTRUCT':
        # Simplified: doesn't handle multiple values from expressions well
        # In jq, {a: (1,2)} yields {a:1} and {a:2}
        # This implementation will be much simpler for now
        res = {}
        for k_expr, v_expr in node[1]:
            # k_expr is string or ('KEY_EXPR', ...)
            if isinstance(k_expr, tuple) and k_expr[0] == 'KEY_EXPR':
                keys = list(execute(k_expr[1], value))
                k = keys[0] if keys else None
            else:
                k = k_expr

            vals = list(execute(v_expr, value))
            res[k] = vals[0] if vals else None
        yield res
    elif ntype == 'FUNC':
        name = node[1]
        args = node[2]
        if name == 'map':
            # map(f) is [.[] | f]
            inner_filter = ('PIPE', [('ITER',), args[0]])
            yield list(execute(inner_filter, value))
        elif name == 'select':
            # select(f)
            for cond in execute(args[0], value):
                if cond not in (False, None):
                    yield value
        elif name == 'keys':
            if isinstance(value, dict):
                yield sorted(value.keys())
            elif isinstance(value, list):
                yield list(range(len(value)))
        elif name == 'length':
            if isinstance(value, (list, dict, str)):
                yield len(value)
            elif value is None:
                yield 0
            else:
                yield 0 # Should check jq's behavior
        else:
            # ignore unknown functions for now
            pass

def main():
    parser = argparse.ArgumentParser(add_help=False)
    parser.add_argument("-c", "--compact-output", action="store_true")
    parser.add_argument("-r", "--raw-output", action="store_true")
    parser.add_argument("-s", "--slurp", action="store_true")
    parser.add_argument("-n", "--null-input", action="store_true")
    parser.add_argument("-S", "--sort-keys", action="store_true")
    parser.add_argument("-r0", "--raw-output0", action="store_true")
    parser.add_argument("-j", "--join-output", action="store_true")
    parser.add_argument("--indent", type=int)
    parser.add_argument("-V", "--version", action="store_true")
    parser.add_argument("-h", "--help", action="store_true")

    args, unknown = parser.parse_known_args()

    if args.version:
        print("jq-build-2b77eb1")
        return

    filter_str = "."
    files = []

    if unknown:
        filter_str = unknown[0]
        files = unknown[1:]

    try:
        tokens = Tokenizer(filter_str).tokens
        parsed_filter = Parser(tokens).parse()
    except Exception as e:
        # sys.stderr.write(f"Error parsing filter: {e}\n")
        # In case of error, jq usually prints to stderr and exits with 2
        sys.exit(2)

    inputs = []
    if args.null_input:
        inputs = [None]
    else:
        if not files:
